"use strict";(globalThis.webpackChunkwarptorch_docs=globalThis.webpackChunkwarptorch_docs||[]).push([[389],{4133(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome","metadata":{"permalink":"/WarpTorch/blog/welcome","editUrl":"https://github.com/just-omar/WarpTorch/tree/main/documentation/blog/2024-05-23-welcome/index.md","source":"@site/blog/2024-05-23-welcome/index.md","title":"Welcome to WarpTorch Documentation","description":"Welcome to the official WarpTorch documentation! This blog will keep you updated with the latest developments, tutorials, and research in GPU-accelerated general relativity simulations.","date":"2024-05-23T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/WarpTorch/blog/tags/announcement"},{"inline":true,"label":"warptorch","permalink":"/WarpTorch/blog/tags/warptorch"},{"inline":true,"label":"release","permalink":"/WarpTorch/blog/tags/release"}],"readingTime":1.12,"hasTruncateMarker":true,"authors":[{"name":"Omar","title":"WarpTorch Developer","url":"https://github.com/just-omar","email":"omar@warptorch.org","twitter":"just_omar","linkedin":"just-omar","github":"just-omar","imageURL":"https://github.com/just-omar.png","key":"omar","page":null}],"frontMatter":{"slug":"welcome","title":"Welcome to WarpTorch Documentation","authors":["omar"],"tags":["announcement","warptorch","release"]},"unlisted":false,"nextItem":{"title":"Contributing to WarpTorch: A Guide","permalink":"/WarpTorch/blog/collaboration-guide"}},"content":"Welcome to the official WarpTorch documentation! This blog will keep you updated with the latest developments, tutorials, and research in GPU-accelerated general relativity simulations.\\n\\n\x3c!-- truncate --\x3e\\n\\n## What is WarpTorch?\\n\\nWarpTorch is a high-performance, GPU-accelerated General Relativity toolkit designed for simulating, analyzing, and visualizing warp drive spacetimes. By porting and optimizing numerical relativity methods to modern PyTorch, we enable physicists and enthusiasts to solve Einstein\'s field equations at unprecedented speeds.\\n\\n## Key Features\\n\\n- **Massive Acceleration**: GPU-accelerated tensor computations with CUDA, ROCm, and Intel Arc support\\n- **Comprehensive Library**: Vectorized implementations of classical and novel warp metrics\\n- **Advanced Solvers**: 4th-order finite difference stencils for Einstein\'s field equations\\n- **Web-Ready Export**: JSON exporters for WebGL frontend integration\\n\\n## Getting Started\\n\\nCheck out our [quick start guide](/docs/quick-start) to get started with WarpTorch. Whether you prefer interactive 3D visualization in your browser or direct Python programming in Jupyter Lab, we have you covered.\\n\\n## Stay Tuned\\n\\nFollow this blog for:\\n- **Tutorials**: Step-by-step guides for warp drive simulations\\n- **Research Updates**: Latest developments in warp drive physics\\n- **Performance Tips**: Optimize your simulations for maximum speed\\n- **Community Highlights**: Interesting projects from the WarpTorch community\\n\\n## Join the Community\\n\\n- **GitHub**: [https://github.com/just-omar/WarpTorch](https://github.com/just-omar/WarpTorch)\\n- **Issues**: Report bugs and request features\\n- **Contributions**: We welcome contributions from the community\\n\\nWelcome aboard the WarpTorch project! \ud83d\ude80"},{"id":"collaboration-guide","metadata":{"permalink":"/WarpTorch/blog/collaboration-guide","editUrl":"https://github.com/just-omar/WarpTorch/tree/main/documentation/blog/2024-05-23-collaboration/index.md","source":"@site/blog/2024-05-23-collaboration/index.md","title":"Contributing to WarpTorch: A Guide","description":"We\'re excited to welcome contributions from the community! This guide will help you get started with contributing to WarpTorch.","date":"2024-05-23T00:00:00.000Z","tags":[{"inline":true,"label":"community","permalink":"/WarpTorch/blog/tags/community"},{"inline":true,"label":"contribution","permalink":"/WarpTorch/blog/tags/contribution"},{"inline":true,"label":"guide","permalink":"/WarpTorch/blog/tags/guide"}],"readingTime":1.8,"hasTruncateMarker":true,"authors":[{"name":"Omar","title":"WarpTorch Developer","url":"https://github.com/just-omar","email":"omar@warptorch.org","twitter":"just_omar","linkedin":"just-omar","github":"just-omar","imageURL":"https://github.com/just-omar.png","key":"omar","page":null}],"frontMatter":{"slug":"collaboration-guide","title":"Contributing to WarpTorch: A Guide","authors":["omar"],"tags":["community","contribution","guide"]},"unlisted":false,"prevItem":{"title":"Welcome to WarpTorch Documentation","permalink":"/WarpTorch/blog/welcome"}},"content":"We\'re excited to welcome contributions from the community! This guide will help you get started with contributing to WarpTorch.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Why Contribute?\\n\\nWarpTorch is a community-driven project focused on making GPU-accelerated general relativity simulations accessible to everyone. Whether you\'re a physicist, developer, or enthusiast, your contributions matter!\\n\\n## Ways to Contribute\\n\\n### Code Contributions\\n- Fix bugs and implement new features\\n- Optimize existing CUDA kernels\\n- Add support for new spacetime metrics\\n- Improve documentation\\n\\n### Research & Science\\n- Contribute novel warp drive metrics\\n- Share simulation results\\n- Write physics tutorials\\n- Validate numerical methods\\n\\n### Community\\n- Help new users on GitHub Issues\\n- Write blog posts about your projects\\n- Share WarpTorch on social media\\n- Organize study groups\\n\\n## Getting Started\\n\\n1. **Fork the repository** on GitHub\\n2. **Clone your fork**: `git clone https://github.com/YOUR_USERNAME/WarpTorch`\\n3. **Create a branch**: `git checkout -b feature/my-feature`\\n4. **Make your changes** and test thoroughly\\n5. **Submit a pull request** with a clear description\\n\\n## Coding Standards\\n\\n- Follow the existing code style\\n- Add docstrings to new functions\\n- Include tests for new features\\n- Update relevant documentation\\n\\n## What We\'re Looking For\\n\\n### High Priority\\n- Performance optimizations for CUDA kernels\\n- Additional spacetime metrics\\n- Better error handling and validation\\n- Improved test coverage\\n\\n### Medium Priority\\n- Documentation improvements\\n- Bug fixes\\n- UI/UX enhancements\\n- Example notebooks\\n\\n### Nice to Have\\n- New visualization features\\n- Additional export formats\\n- Integration with other physics libraries\\n- Multi-language support\\n\\n## Recognition\\n\\nAll contributors are:\\n- Listed in our contributors section\\n- Mentioned in release notes\\n- Eligible for contributor badges\\n- Part of our decision-making process\\n\\n## Join the Team\\n\\nActive contributors may be invited to join the core team! Core team members have:\\n- Write access to the repository\\n- Voting rights on project decisions\\n- Official contributor status\\n- Access to development resources\\n\\n## Resources\\n\\n- **GitHub**: [https://github.com/just-omar/WarpTorch](https://github.com/just-omar/WarpTorch)\\n- **Issues**: Report bugs and request features\\n- **Discussions**: Ask questions and share ideas\\n- **Documentation**: [https://warptorch.org](https://warptorch.org)\\n\\n## Next Steps\\n\\nReady to contribute? Check out our [good first issues](https://github.com/just-omar/WarpTorch/issues?q=is%3Aissue+is%3Aopen+label%3A%22good+first+issue%22) or start with the [documentation](/docs/intro)!\\n\\n---\\n\\n*This guide will be updated as the project grows. Have suggestions? Open an issue or PR!*"}]}}')}}]);